// Deduplicate frames using Redis
const redis = await getRedisClient();
const frame = items[0].json;
const cacheKey = `frame-hash:${frame.agent_id}:${frame.p_hash}`;
const exists = await redis.get(cacheKey);
if (exists) {
  return [];
}
await redis.set(cacheKey, frame.frame_id, 'EX', 5);
return items;

const frame = items[0].json;
const state = await redisGet(`state:${frame.agent_id}`) || {};
const systemPrompt = `You are an RDP analysis assistant. Respond with JSON matching the schema {\"intent\": \"classify|act|noop\", \"confidence\": number, \"action\": {\"type\": string, \"target\": string|null, \"value\": string|null}, \"state_delta\": object|null, \"reason\": string}`;`;
items[0].json = {
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: JSON.stringify({
        ocr_text: frame.ocr_text,
        signals: frame.signals,
        last_state: state,
        metadata: frame.meta
    }) }
  ],
  frame
};
return items;

const frame = items[0].json.frame;
const decision = JSON.parse(items[0].json.data[0].json.choices[0].message.content);
await redisSet(`state:${frame.agent_id}`, decision.state_delta || {}, 3600);
return [{ json: { frame, decision } }];
